fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

fn sim(n: u64) -> SimId {
    SimId::try_from(n).expect("valid")
}

/// The repository's data with the search height `c` of the market.
fn market_data(height: f64) -> Data {
    let (calibration, genome_map) = common::files();
    let mut demography = common::demography();
    demography["values"]["core:market_search_height_female"]["value"] = serde_json::json!(height);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

fn market_start() -> Input {
    let founder = |years: i64, sex: Sex| Founder {
        born: SimTime::from_secs(-years * Y),
        sex,
        alleles: Vec::new(),
    };
    Input::Start(Start {
        world_seed: 0xff,
        founder_tag: DataId::new("test:market").expect("valid"),
        world_params: WorldParams {
            hereditary_diseases: false,
            nutrition: Vec::new(),
        },
        founders: vec![
            founder(20, Sex::Female),
            founder(24, Sex::Male),
            founder(21, Sex::Female),
            founder(25, Sex::Male),
            founder(22, Sex::Female),
            founder(23, Sex::Male),
            founder(20, Sex::Female),
            founder(21, Sex::Female),
            founder(25, Sex::Male),
            founder(40, Sex::Male),
        ],
        couples: vec![
            Couple { woman: 0, man: 1 },
            Couple { woman: 2, man: 3 },
            Couple { woman: 4, man: 5 },
        ],
    })
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
}

impl Run {
    fn market() -> Run {
        let mut world = World::new(market_data(1.0));
        world.submit(market_start()).expect("accepted");
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
        }
    }

    fn advance(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }

    /// The partnerships formed so far as (woman, man, formed).
    fn pairs(&self) -> Vec<(u64, u64, i64)> {
        self.world
            .state()
            .pedigree()
            .partnerships
            .iter()
            .map(|p| (p.woman.get(), p.man.get(), p.formed.as_secs()))
            .collect()
    }
}

#[test]
fn the_test_data_of_market() {
    assert_eq!(market_data(1.0).hash(), MARKET_DATA_HASH);
}

/// Round 1: the single women 7 and 8 both search, sim 8 first by her rank; both choose
/// sim 9. Sim 8 gets him (partnership 4, an entry with the plan of the round, the rule and
/// the noise of the chosen candidate as causes); sim 7 gets nobody and no second try. In
/// round 2 she chooses the man of 40, the only single man left.
#[test]
fn the_first_rounds_pair_the_single_founders() {
    let mut run = Run::market();
    run.advance(MONTH - 1);
    assert_eq!(run.save(), hex(MARKET_SAVE_BEFORE_PAIRING_ROUND));
    let before = run.log.len();
    run.advance(MONTH);
    assert_eq!(run.log.len(), before + 1);
    assert_eq!(
        postcard::to_allocvec(&run.log[before]).expect("encodes"),
        hex(MARKET_PARTNERED_ENTRY)
    );
    assert_eq!(
        serde_json::to_string(&run.log[before]).expect("json"),
        PARTNERED_JSON
    );
    assert_eq!(run.save(), hex(MARKET_SAVE_AFTER_PAIRING_ROUND));
    run.advance(2 * MONTH);
    assert_eq!(
        run.pairs()[3..],
        [(8, 9, MONTH), (7, 10, 2 * MONTH)],
        "the couples of `Start` are partnerships 1 to 3"
    );
}

/// Round 478: the searching girl of 17 (sim 24) has her first cousin (sim 26, φ = 1/16,
/// the penalty ln 10) and a stranger (sim 27) in her list; she takes the stranger. The
/// woman of 31 before her (sim 23) skips both, her nephews (φ = 1/8), and finds nobody.
#[test]
fn a_cousin_in_the_list_pays_the_penalty() {
    let mut run = Run::market();
    run.advance(478 * MONTH - 1);
    assert_eq!(run.save(), hex(MARKET_SAVE_BEFORE_COUSIN_ROUND));
    let before = run.log.len();
    run.advance(478 * MONTH);
    assert_eq!(run.log.len(), before + 1);
    assert_eq!(
        postcard::to_allocvec(&run.log[before]).expect("encodes"),
        hex(MARKET_COUSIN_ROUND_ENTRY)
    );
    assert_eq!(
        serde_json::to_string(&run.log[before]).expect("json"),
        COUSIN_ROUND_JSON
    );
    assert_eq!(run.save(), hex(MARKET_SAVE_AFTER_COUSIN_ROUND));
}

/// Forty years of "market": 17 partnerships, among them the girl of 17 who skips her twin
/// brother (round 238, she pairs with sim 16) and the boy chosen on his 16th birthday
/// (round 502, sim 31 by sim 23); nobody is paired below 16.
#[test]
fn forty_years_of_market() {
    let mut run = Run::market();
    run.advance(40 * Y - 1);
    let pairs = run.pairs();
    assert_eq!(pairs.len(), 17);
    assert!(pairs.contains(&(14, 16, 238 * MONTH)));
    assert!(pairs.contains(&(23, 31, 502 * MONTH)));
    let born = |id: u64| run.world.state().born(sim(id)).expect("known").as_secs();
    assert!(
        pairs
            .iter()
            .all(|&(woman, man, formed)| [woman, man].iter().all(|p| formed - born(*p) >= 16 * Y))
    );
    let partnered = run
        .log
        .iter()
        .filter(|entry| matches!(entry.payload, LogPayload::Partnered { .. }))
        .count();
    assert_eq!(partnered, 17);
    assert_eq!(run.save(), hex(MARKET_SAVE_END_OF_YEAR_39));
    let hashes: Vec<u64> = run.out.year_hashes.iter().map(|year| year.hash).collect();
    assert_eq!(hashes, MARKET_YEAR_HASHES);
    assert_eq!(log_hash(&run.log), MARKET_LOG_HASH);
}

/// `ArrangePartnership` below the market age and between close kin is rejected (ADR-0018
/// section 1): sim 12 turns 16 in month 223 (second 539 481 600); an arrangement acting a
/// second before is too young, one acting in that second pairs her; the twins 14 and 13
/// (φ = 1/4) are too closely related.
#[test]
fn an_arrangement_needs_the_market_age_and_no_close_kin() {
    let arrange = |woman: u64, man: u64| {
        Input::ArrangePartnership(ArrangePartnership {
            woman: sim(woman),
            man: sim(man),
        })
    };
    let mut run = Run::market();
    run.advance(539_481_598);
    assert_eq!(
        run.world.submit(arrange(12, 11)).err(),
        Some(InputRejected {
            code: RejectCode::PartnerTooYoung
        })
    );
    run.advance(539_481_599);
    run.world.submit(arrange(12, 11)).expect("accepted");
    let mut run = Run::market();
    run.advance(575_769_599);
    assert_eq!(
        run.world.submit(arrange(14, 13)).err(),
        Some(InputRejected {
            code: RejectCode::PartnersTooCloselyRelated
        })
    );
}

/// Saving and loading between rounds changes nothing: the kinship cache starts empty after
/// a load (ADR-0018 section 2) and every φ comes out the same.
#[test]
fn save_load_continue_across_rounds() {
    let end = 40 * Y - 1;
    let mut whole = Run::market();
    whole.advance(end);
    for stop in [
        MONTH - 1,
        MONTH,
        238 * MONTH,
        478 * MONTH - 1,
        478 * MONTH,
        30 * Y,
    ] {
        let mut part = Run::market();
        part.advance(stop);
        let bytes = part.save();
        let (loaded, years) = World::load(&bytes, market_data(1.0)).expect("loads");
        assert_eq!(loaded.save(&years).expect("saves"), bytes, "stop {stop}");
        let mut rest = Run {
            world: loaded,
            out: YearOut {
                census: part.out.census.clone(),
                year_hashes: years,
            },
            log: part.log,
        };
        rest.advance(end);
        assert_eq!(rest.out.year_hashes, whole.out.year_hashes, "stop {stop}");
        assert_eq!(log_hash(&rest.log), log_hash(&whole.log), "stop {stop}");
        assert_eq!(
            rest.world.state_hash(),
            whole.world.state_hash(),
            "stop {stop}"
        );
    }
}
